from typing import Dict

def get_logical_path_map(inventory: Dict[str, Dict[str, str]], version: str) -> Dict[str, str]:
    """
    Returns a dictionary mapping state names to file paths based on the provided inventory and version.

    Args:
        inventory (Dict[str, Dict[str, str]]): A dictionary representing the inventory structure.
        version (str): A string representing the version of the inventory.

    Returns:
        Dict[str, str]: A dictionary where keys are state names and values are their corresponding file paths.
    """
    logical_path_map = {}

    for state, details in inventory.items():
        if version in details.get('versions', []):
            logical_path_map[state] = details['path']

    return logical_path_map


