from typing import Any, List, Optional
from lxml import etree


def match_pubdate(node: Any, pubdate_xpaths: List[str]) -> Optional[str]:
    """For the given node, returns the first match in the pubdate_xpaths list."""
    if not pubdate_xpaths:
        return None

    # Ensure the node is an Element object
    if not isinstance(node, etree._Element):
        try:
            parsed_node = etree.fromstring(str(node))
        except etree.XMLSyntaxError:
            return None
    else:
        parsed_node = node

    for xpath in pubdate_xpaths:
        # Execute the XPath expression on the parsed node
        match = parsed_node.xpath(xpath)

        if match:
            # Ensure the match is a string or has non-None text
            if isinstance(match[0], str):
                return match[0]
            elif isinstance(match[0], etree._Element) and match[0].text is not None:
                return match[0].text

    # Return None if no match is found
    return None

