from typing import List
from typing import Dict, Any

def _dictsum(*dicts: Dict[str, int]) -> Dict[str, int]:
    """
    Sum the values of common keys across multiple dictionaries.

    Args:
        *dicts: Variable number of dictionaries with string keys and integer values.

    Returns:
        A dictionary with summed values for common keys.
    """
    result = {}
    for dictionary in dicts:
        for key, value in dictionary.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

