from typing import List
import inspect
import pkgutil
import importlib


def subclasses(cls: type) -> List[type]:
    """
    Returns a list of all subclasses of the given class, including those at multiple levels of inheritance.

    Args:
        cls (type): The class for which to find all subclasses.

    Returns:
        List[type]: A list of class objects representing all subclasses of `cls`.
    """
    subclasses_list = []

    # Iterate over all modules in the current package
    for _, modname, _ in pkgutil.iter_modules(__package__ is None and [__name__] or [__package__]):
        try:
            module = importlib.import_module(modname)
            for name, obj in inspect.getmembers(module):
                if inspect.isclass(obj) and issubclass(obj, cls) and obj != cls:
                    subclasses_list.append(obj)
        except ImportError:
            continue

    return subclasses_list


# Example usage
if __name__ == "__main__":
    class Animal:
        pass

    class Dog(Animal):
        pass

    class Cat(Animal):
        pass

    class GoldenRetriever(Dog):
        pass

    print(subclasses(Animal))  # Should print: [<class '__main__.Dog'>, <class '__main__.Cat'>, <class '__main__.GoldenRetriever'>]

