from typing import List, Dict, Any

def from_raw_values(values: List[str]) -> Dict[str, Any]:
    """
    Converts a list of raw bookmark strings into a structured format.

    Args:
        values (List[str]): A list of raw bookmark strings.

    Returns:
        Dict[str, Any]: A dictionary representing the structured bookmarks.
    """
    structured_bookmarks = {}
    for index, value in enumerate(values):
        if not value.strip():
            continue
        try:
            # Split the value at most once to separate the URL and title
            url, *rest = value.split(maxsplit=1)
            title = rest[0].strip() if rest else ""
            bookmark_id = f"bookmark_{index + 1}"
            structured_bookmarks[bookmark_id] = {
                "url": url,
                "title": title
            }
        except ValueError as e:
            # Raise a ValueError with a descriptive message
            raise ValueError(f"Invalid bookmark format: {value}") from e
    return structured_bookmarks

# Example usage
if __name__ == "__main__":
    raw_bookmarks = [
        "http://example.com Example Title",
        "http://example.org Another Title",
        "",
        "Invalid Bookmark"
    ]
    try:
        print(from_raw_values(raw_bookmarks))
    except ValueError as e:
        print(e)
